/// Depth layers. Inset layers are not included: BoxShadow cannot draw them.
@immutable
class WxShadows {
  const WxShadows({required this.xs, required this.sm, required this.md, required this.lg, required this.xl, required this.raised, required this.pressed, required this.field});
  final List<BoxShadow> xs;
  final List<BoxShadow> sm;
  final List<BoxShadow> md;
  final List<BoxShadow> lg;
  final List<BoxShadow> xl;
  final List<BoxShadow> raised;
  final List<BoxShadow> pressed;
  final List<BoxShadow> field;

  static const light = WxShadows(
    xs: [BoxShadow(offset: Offset(0, 1), blurRadius: 2, spreadRadius: 0, color: Color(0x0F18160A))],
    sm: [BoxShadow(offset: Offset(0, 1), blurRadius: 3, spreadRadius: 0, color: Color(0x1418160A))],
    md: [BoxShadow(offset: Offset(0, 4), blurRadius: 10, spreadRadius: -3, color: Color(0x1F18160A)), BoxShadow(offset: Offset(0, 1), blurRadius: 2, spreadRadius: 0, color: Color(0x0F18160A))],
    lg: [BoxShadow(offset: Offset(0, 10), blurRadius: 24, spreadRadius: -8, color: Color(0x2E18160A)), BoxShadow(offset: Offset(0, 1), blurRadius: 3, spreadRadius: 0, color: Color(0x0D18160A))],
    xl: [BoxShadow(offset: Offset(0, 20), blurRadius: 44, spreadRadius: -12, color: Color(0x4218160A)), BoxShadow(offset: Offset(0, 1), blurRadius: 3, spreadRadius: 0, color: Color(0x0F18160A))],
    raised: [BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x2B18160A)), BoxShadow(offset: Offset(0, 1), blurRadius: 3, spreadRadius: 0, color: Color(0x1218160A))],
    pressed: [BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x3318160A))],
    field: [],
  );

  static const dark = WxShadows(
    xs: [BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x0DFFFFFF))],
    sm: [BoxShadow(offset: Offset(0, 1), blurRadius: 3, spreadRadius: 0, color: Color(0x80000000)), BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x0FFFFFFF))],
    md: [BoxShadow(offset: Offset(0, 4), blurRadius: 10, spreadRadius: -3, color: Color(0x8C000000)), BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x12FFFFFF))],
    lg: [BoxShadow(offset: Offset(0, 10), blurRadius: 24, spreadRadius: -8, color: Color(0xA6000000)), BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x14FFFFFF))],
    xl: [BoxShadow(offset: Offset(0, 20), blurRadius: 44, spreadRadius: -12, color: Color(0xBF000000)), BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x17FFFFFF))],
    raised: [BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x21FFFFFF)), BoxShadow(offset: Offset(0, 1), blurRadius: 3, spreadRadius: 0, color: Color(0x73000000))],
    pressed: [BoxShadow(offset: Offset(0, 0), blurRadius: 0, spreadRadius: 1, color: Color(0x1AFFFFFF))],
    field: [],
  );
}

/// Round corners, for shapes that are not squircles.
abstract final class WxRadius {
  static const double xs = 5;
  static const double sm = 6;
  static const double md = 10;
  static const double lg = 16;
  static const double xl = 20;
  static const double full = 9999;
}

/// Squircle radii. Controls md, panels lg, dialogs xl.
abstract final class WxSquircle {
  static const double xs = 7;
  static const double sm = 9;
  static const double md = 14;
  static const double lg = 26;
  static const double xl = 30;
}

/// Control heights.
abstract final class WxControl {
  static const double xs = 28;
  static const double sm = 32;
  static const double md = 38;
  static const double lg = 44;
}

/// One step of the type scale, in logical pixels.
@immutable
class WxTextSpec {
  const WxTextSpec({required this.size, required this.lineHeight, required this.letterSpacing, required this.weight});
  final double size;
  final double lineHeight;
  final double letterSpacing;
  final int weight;
}

abstract final class WxTextScale {
  static const displayXl = WxTextSpec(size: 56, lineHeight: 64, letterSpacing: -1.96, weight: 700);
  static const displayLg = WxTextSpec(size: 44, lineHeight: 52, letterSpacing: -1.32, weight: 700);
  static const displayMd = WxTextSpec(size: 36, lineHeight: 44, letterSpacing: -1.008, weight: 700);
  static const headingXl = WxTextSpec(size: 30, lineHeight: 38, letterSpacing: -0.72, weight: 700);
  static const headingLg = WxTextSpec(size: 24, lineHeight: 32, letterSpacing: -0.48, weight: 700);
  static const headingMd = WxTextSpec(size: 19, lineHeight: 26, letterSpacing: -0.304, weight: 700);
  static const headingSm = WxTextSpec(size: 17, lineHeight: 24, letterSpacing: -0.204, weight: 700);
  static const bodyLg = WxTextSpec(size: 17, lineHeight: 28, letterSpacing: -0.051, weight: 400);
  static const bodyMd = WxTextSpec(size: 15, lineHeight: 24, letterSpacing: 0, weight: 400);
  static const bodySm = WxTextSpec(size: 14, lineHeight: 22, letterSpacing: 0, weight: 400);
  static const caption = WxTextSpec(size: 13, lineHeight: 18, letterSpacing: 0.039, weight: 400);
  static const overline = WxTextSpec(size: 12, lineHeight: 16, letterSpacing: 0.72, weight: 600);
}

/// The type scale by name. WxType supplies the font.
mixin WxTypeScale {
  TextStyle style(WxTextSpec spec);

  TextStyle get displayXl => style(WxTextScale.displayXl);
  TextStyle get displayLg => style(WxTextScale.displayLg);
  TextStyle get displayMd => style(WxTextScale.displayMd);
  TextStyle get headingXl => style(WxTextScale.headingXl);
  TextStyle get headingLg => style(WxTextScale.headingLg);
  TextStyle get headingMd => style(WxTextScale.headingMd);
  TextStyle get headingSm => style(WxTextScale.headingSm);
  TextStyle get bodyLg => style(WxTextScale.bodyLg);
  TextStyle get bodyMd => style(WxTextScale.bodyMd);
  TextStyle get bodySm => style(WxTextScale.bodySm);
  TextStyle get caption => style(WxTextScale.caption);
  TextStyle get overline => style(WxTextScale.overline);
}

abstract final class WxDurations {
  static const instant = Duration(milliseconds: 70);
  static const fast = Duration(milliseconds: 110);
  static const base = Duration(milliseconds: 150);
  static const slow = Duration(milliseconds: 220);
  static const move = Duration(milliseconds: 150);
  static const enter = Duration(milliseconds: 270);
}

abstract final class WxEase {
  static const out = Cubic(0.16, 1, 0.3, 1);
  static const inOut = Cubic(0.65, 0, 0.35, 1);
  static const standard = Cubic(0.2, 0, 0, 1);
  static const move = Cubic(0.2, 0.9, 0.25, 1);
}
